  /* ---------- Giấy tờ của đơn vị (chỉ chủ đơn vị) ---------- */
  /* Số ngày từ hôm nay 24/09/2026 tới ngày dd/mm/yyyy; âm là đã quá hạn */
  function daysTo(dmy) { var p = dmy.split('/'); return Math.round((new Date(+p[2], +p[1] - 1, +p[0]) - new Date(VN.today.y, VN.today.m - 1, VN.today.d)) / 864e5); }
  function docAll(d) { return !d[5] || d[5][1] === 'All categories'; }
