    ACT.ft = function (el) { a.S.form.ft = el.dataset.id; a.render(); };
    ACT.availToggle = function () { a.S.avail = !a.S.avail; a.render(); a.toast(a.S.avail ? L('Đang nhận yêu cầu', 'Accepting requests') : L('Đã tạm ngưng nhận yêu cầu mới', 'Stopped accepting new requests'), 'info'); };
    ACT.pickSlot = function (el) { a.S.form.slot = el.dataset.id; a.render(); };
    ACT.reqConfirm = function (el) {
      var r = R(a, el.dataset.id); r.st = 'waiting'; r.slot = a.S.form.slot; a.S.form.slot = null; a.S.form.rt = 'waiting'; a.back();
      a.toast(L('Đã xác nhận ' + fmtSlot(r.slot) + '. Chờ khách chọn', 'Confirmed ' + fmtSlot(r.slot) + '. Awaiting the customer'));
      if (a.S.custOK) setTimeout(function () { r.st = 'won'; r.order = 'VN-2409' + (40 + a.S.reqSeq++ % 50); var st0 = parseInt(r.slot.split(' ')[1], 10); a.S.unassigned.push({ id: r.order, svc: [r.svc[0] + ' · ' + r.spec[0].split(' · ')[0], r.svc[1] + ' · ' + r.spec[1].split(' · ')[0]], time: r.slot.split(' ')[1], ward: r.ward, due: VN.pad(st0 - 2) + ':00', cust: r.cust }); a.render(); a.toast(L('Khách đã chọn bạn cho ' + r.id + '. Hãy phân công', 'The customer chose you for ' + r.id + '. Assign someone'), 'info'); }, 3500);
    };
    ACT.sheetDecline = function (el) { a.sheet('decline', { id: el.dataset.id }); };
