    ACT.declineGo = function (el) { var r = R(a, el.dataset.id); r.st = 'lost'; a.S.sheet = null; a.back(); a.toast(L('Đã từ chối ', 'Declined ') + r.id); };
    ACT.sheetAssign = function (el) { a.sheet('assign', { id: el.dataset.id }); };
    ACT.assign = function (el) {
      var id = el.dataset.id, m = a.S.team.filter(function (x) { return x.id === el.dataset.x; })[0], u = a.S.unassigned.filter(function (x) { return x.id === id; })[0];
      a.S.unassigned = a.S.unassigned.filter(function (x) { return x.id !== id; });
      var hh = parseInt(u.time, 10); m.jobs.push([hh, hh + 2, id, 'slate']); a.S.sheet = null; a.render();
      a.toast(L('Đã phân công ' + id + ' cho ' + m.n + '. Khách được báo tên kỹ thuật viên', id + ' assigned to ' + m.n + '. Customer notified'));
    };
    ACT.shift = function (el) { var s = a.S.form['sh-' + el.dataset.id]; s[+el.dataset.x] = s[+el.dataset.x] ? 0 : 1; a.render(); };
    ACT.techToggle = function (el) { var m = a.S.team.filter(function (x) { return x.id === el.dataset.id; })[0]; m.on = !m.on; a.render(); a.toast(m.on ? L('Đã bật tài khoản ', 'Enabled ') + m.n : L('Đã tắt tài khoản ', 'Disabled ') + m.n); };
    ACT.sheetInvite = function () { a.sheet('invite', { ph: '' }); };
    ACT.inviteGo = function () { var ph = a.S.sheet.ph; a.S.team.push({ id: 'new' + a.S.team.length, n: ph, ini: '?', st: 'off', skills: ['Điện lạnh'], jobs: [], rating: 0, done: 0, cancel: 0, ontime: 0, cert: [1, 1, 2027], on: false, pending: true }); a.S.sheet = null; a.render(); a.toast(L('Đã gửi lời mời tới ', 'Invite sent to ') + ph); };
    ACT.wdSet = function (el) { a.S.form.wd = el.dataset.id; a.render(); };
    IN.wd = function (el, v) { a.S.form.wd = v; a.render(); };
    ACT.wdGo = function () { var amt = VN.parseMoney(a.S.form.wd == null ? a.S.bal.avail - debtSum(a) : a.S.form.wd); a.S.bal.avail -= amt; a.S.bal.payout += amt; a.S.payouts.unshift(['RT-24' + (a.S.reqSeq++ % 1000), amt, 5500, '24/09 ' + VN.nowTime(), 'pending']); a.S.form.wd = null; a.S.form.ft = 'payouts'; a.back(); a.toast(L('Đã gửi yêu cầu rút ', 'Payout requested: ') + money(amt)); };
    ACT.export = function () { a.toast(L('Đã tạo file đối soát tháng 09/2026', 'Statement for September 2026 created')); };
    ACT.sheetRole = function () { a.sheet('role'); };
    ACT.role = function (el) { setRole(a, el.dataset.id); };
    ACT.sheetLang = function () { a.sheet('lang'); };
    ACT.docUp = function (el) {
      var i = +el.dataset.id, d = a.S.docs[i];
      if (!d || a.S.role !== 'owner' || d[2] === 'review' || a.S.uploading != null) return;
      a.S.uploading = i; a.render();
      setTimeout(function () {
        a.S.uploading = null; d[2] = 'review'; d[1] = '12/09/2029'; d[3] = VN.dmy(VN.today.d, VN.today.m, VN.today.y); d[4] = '';
        a.render(); a.toast(L('Đã tải bản mới, chờ nền tảng duyệt', 'Uploaded, awaiting review'));
      }, 900);
    };
    ACT.catT = function (el) { a.S.cats[el.dataset.id] = !a.S.cats[el.dataset.id]; a.render(); };
    ACT.sheetPrice = function (el) { a.sheet('price', { i: +el.dataset.id }); };
