    IN.radius = function (el, v) { a.S.radius = +v; a.render(); };
    ACT.dayT = function (el) { var d = a.S.hours[+el.dataset.id]; d[2] = !d[2]; if (d[2] && !d[3]) d[3] = '08:00-12:00'; a.render(); };
